{
  "versao": 1,
  "prospect": "Verdeluz Cosméticos Veganos",
  "problemas": [
    {
      "id": "P1",
      "tema": "eficiencia-midia",
      "titulo": "Eficiência da mídia paga em queda",
      "origem": "03 · ROAS, custo por sessão, conversão e dependência; 04 · CAC e LTV/CAC",
      "dado": "De OUT a SET o investimento subiu 127% (R$ 14,5 mil para R$ 32,9 mil) e a receita captada só 7,3%. ROAS global de 6,5x para 3,1x, Meta em 0,8x em SET (abaixo de 1x desde JUL) e conversão do Meta em 0,70%. CAC de R$ 49,5 para R$ 112,7, com os mesmos 292 clientes novos em OUT e SET. LTV/CAC de SET em 2,77. Dependência de mídia paga de 44,8% (JUN) para 54,7% (SET).",
      "benchmark": "LTV/CAC: abaixo de 3 é ruim, de 3 a 5 normal, acima de 5 escala. Dependência de mídia paga: 45% a 60% (DTC consolidada). Conversão Meta de 1% a 2% e Google de 2% a 4%. Referência de mercado, fonte a confirmar. ROAS e CAC não têm faixa em benchmarks-kpi.md.",
      "hipoteses": [
        { "id": "H1", "texto": "O público pago está saturado: o investimento subiu 127% e os clientes novos ficaram estáveis em 292." },
        { "id": "H2", "texto": "O Meta traz tráfego frio sem qualificação: ROAS de 0,8x e conversão de 0,70% com 62% da verba." },
        { "id": "H3", "texto": "A verba cresce sem regra de parada: não há teto de CAC nem ROAS mínimo por plataforma." }
      ],
      "solucoes": [
        { "id": "P1.S1", "acao": "Adotar o CAC de R$ 103,9 (o que dá LTV/CAC de 3x) como teto, com ROAS mínimo por plataforma, para decidir escalar ou pausar a cada quinzena.", "hipotese": "H3" },
        { "id": "P1.S2", "acao": "Separar no Meta a prospecção do remarketing, cada um com ROAS-alvo próprio, e cortar a prospecção que ficar abaixo de 1x.", "hipotese": "H2" },
        { "id": "P1.S3", "acao": "Congelar o aumento de verba até o CAC voltar abaixo do teto e depois escalar em degraus, liberando o próximo só com o CAC dentro do teto.", "hipotese": "H1" }
      ],
      "impacto": {
        "tipo": "R$",
        "valor": "Economia de R$ 2,6 mil por mês no teto de R$ 103,9, até R$ 11,9 mil por mês se o CAC voltar à média do período (R$ 71,9)",
        "calculo": "investimento de SET (R$ 32.901) menos 292 clientes novos vezes o CAC alvo; premissa: os mesmos 292 clientes novos. É custo evitado de mídia, não receita, e não se soma aos demais. Só SET passa do teto, por isso o ganho no teto é pequeno."
      },
      "frente": "Mídia Paga / Canal Principal"
    },
    {
      "id": "P2",
      "tema": "ruptura-estoque",
      "titulo": "Ruptura do sérum e concentração em três produtos",
      "origem": "03 · Curva ABC e conexão dos KPIs",
      "dado": "Sérum de vitamina C, hidratante gel-creme e protetor FPS 50 fazem 51% da receita. O sérum tem cerca de 7 dias de cobertura (hidratante cerca de 58 e protetor cerca de 70). Em MAR e ABR, com a ruptura citada no kickoff, a conversão foi de 1,05% e 1,00%, com sessões de 38,8 mil e 40,4 mil.",
      "benchmark": "Cobertura de estoque não tem faixa em benchmarks-kpi.md. Referência do cliente: estoque de segurança de 60 dias para os três líderes, com prazo do laboratório de 45 dias. Conversão global de 1% a 2%: MAR e ABR ficaram na faixa, mas entre as menores do ano.",
      "hipoteses": [
        { "id": "H1", "texto": "O estoque é gerido sem ligação com a mídia: o anúncio segue rodando com o sérum perto de acabar." },
        { "id": "H2", "texto": "O prazo do laboratório é de 45 dias e o fornecedor de embalagem do sérum é único." },
        { "id": "H3", "texto": "Três produtos concentram 51% da receita e não há estoque de segurança definido para eles." }
      ],
      "solucoes": [
        { "id": "P2.S1", "acao": "Manter estoque de segurança de 60 dias para os três líderes, com ponto de reposição calculado pelo prazo de 45 dias do laboratório.", "hipotese": "H3" },
        { "id": "P2.S2", "acao": "Qualificar um segundo fornecedor de embalagem para o sérum.", "hipotese": "H2" },
        { "id": "P2.S3", "acao": "Criar a regra de pausa e reativação dos anúncios do produto líder por nível de cobertura, combinada entre expedição, gestor de tráfego e agência.", "hipotese": "H1" }
      ],
      "impacto": {
        "tipo": "R$",
        "valor": "Receita captada em risco de R$ 47 a 65 mil por ocorrência de ruptura (MAR R$ 29,9 mil e ABR R$ 35,3 mil na referência principal)",
        "calculo": "sessões vezes (conversão de referência menos conversão do mês) vezes ticket do mês. Referência principal: média de 1,455% dos 10 meses sem ruptura (R$ 65,2 mil). Referência conservadora: 1,336%, sem NOV, DEZ e MAI (R$ 47,1 mil). Premissa: a conversão é a única causa. É um teto de leitura: em MAR as sessões subiram 27% por tráfego não pago e a conversão já vinha baixa em JAN e FEV (1,25%). Receita captada, antes da quebra."
      },
      "frente": "Eficiência Operacional"
    },
    {
      "id": "P3",
      "tema": "recompra-crm",
      "titulo": "Recompra e CRM sem régua de reposição",
      "origem": "04 · Clientes novos vs recorrentes e LTV; 03 · Aquisição e dependência",
      "dado": "69% dos clientes compraram uma vez só (7.176 de 10.400). Os 31% que recompram geram 57,5% da receita. Clientes novos são 58% a 64% das vendas e os recorrentes cresceram 28% de OUT a SET sem ação ativa. As sessões não pagas ficaram paradas em 16 mil a 19 mil por mês. O sérum dura cerca de 60 dias e o CRM tem um único fluxo (carrinho abandonado) e uma newsletter.",
      "benchmark": "Compra única e ciclo de recompra por categoria estão na lista de pendentes de benchmarks-kpi.md, sem faixa. Referência de LTV/CAC: abaixo de 3 é ruim, e SET está em 2,77.",
      "hipoteses": [
        { "id": "H1", "texto": "Não existe lembrete de reposição, embora o sérum dure cerca de 60 dias." },
        { "id": "H2", "texto": "O CRM tem só um fluxo (carrinho abandonado) e uma newsletter, sem régua de pós-compra nem de reativação." },
        { "id": "H3", "texto": "O cupom de primeira compra atrai quem compra uma vez e não cria hábito de recompra." }
      ],
      "solucoes": [
        { "id": "P3.S1", "acao": "Criar a régua de reposição do sérum, com e-mail aos 45 dias da compra e reforço aos 60.", "hipotese": "H1" },
        { "id": "P3.S2", "acao": "Ativar a reativação dos clientes de compra única aos 90 e aos 150 dias, com conteúdo de rotina e sem desconto.", "hipotese": "H2" },
        { "id": "P3.S3", "acao": "Oferecer a reposição por WhatsApp só a quem der consentimento, começando pelos clientes de uma compra.", "hipotese": "H3" }
      ],
      "impacto": {
        "tipo": "R$",
        "valor": "R$ 7,3 mil de receita bruta por ponto percentual de clientes novos que fazem a segunda compra (+3 pontos: R$ 22,0 mil; +5 pontos: R$ 36,7 mil, como exemplos de premissa, não previsão)",
        "calculo": "3.823 clientes novos do ano vezes 1% vezes 1 pedido extra vezes ticket de R$ 191,8. Premissas: cada cliente que recompra faz só um segundo pedido, o ticket segue o histórico e a conta é em receita, não em margem. Aplicado sobre os 7.176 de compra única seria R$ 13,8 mil por ponto. Mais recompra eleva o LTV e o teto de CAC do P1."
      },
      "frente": "Redução de Dependências"
    },
    {
      "id": "P4",
      "tema": "quebra",
      "titulo": "Quebra de pagamento acima do benchmark e em alta",
      "origem": "03 · Macro financeiro (taxa de quebra)",
      "dado": "Quebra média de 6,3% (6,5% ponderada), acima de 5% em 11 dos 12 meses. Perda de R$ 79,3 mil no ano (receita captada de R$ 1,22 mi contra R$ 1,14 mi aprovada). Pico de 7,9% em NOV e alta mês a mês desde JAN (5,5% para 7,1% em SET). Cartão recusado e PIX expirado não são medidos por meio de pagamento.",
      "benchmark": "Quebra de até 5% (geral, fonte a confirmar). Quebra por PIX e por boleto aparece como pendente em benchmarks-kpi.md.",
      "hipoteses": [
        { "id": "H1", "texto": "Cartão recusado e antifraude estão barrando vendas legítimas." },
        { "id": "H2", "texto": "O PIX expira sem lembrete ao cliente." },
        { "id": "H3", "texto": "Não há medição da quebra por meio de pagamento, então a causa não aparece nos dados." }
      ],
      "solucoes": [
        { "id": "P4.S1", "acao": "Passar a medir a quebra por meio de pagamento (PIX, cartão e boleto) e por motivo de recusa.", "hipotese": "H3" },
        { "id": "P4.S2", "acao": "Recuperar o PIX expirado com lembrete antes do vencimento e um novo QR enviado por e-mail ou WhatsApp.", "hipotese": "H2" },
        { "id": "P4.S3", "acao": "Revisar com o gateway as regras de antifraude e a retentativa de cartão recusado.", "hipotese": "H1" }
      ],
      "impacto": {
        "tipo": "R$",
        "valor": "R$ 18,3 mil de receita aprovada por ano se a quebra cair de 6,5% para 5% (R$ 9,2 mil na metade do caminho, em 5,75%)",
        "calculo": "(quebra ponderada de 6,5% menos 5%) vezes a receita captada de R$ 1.220.462. Conferido contra os R$ 79,3 mil de perda (6,5% da captada). Equivale a 0,84 mês de investimento em mídia. Premissa: só a parte da quebra que é recusa de pagamento é recuperável, e o arquivo não separa as causas. Não considera a receita extra de P2 e P3."
      },
      "frente": "Eficiência Operacional"
    }
  ],
  "pontos_fortes": [
    {
      "titulo": "Conversão global dentro da faixa",
      "dado": "Média de 1,38% no ano, dentro da faixa de 1% a 2% em 11 dos 12 meses",
      "uso": "Prova que o site converte e que o problema está na eficiência da mídia e nas pontas do funil, não na loja."
    },
    {
      "titulo": "Recorrentes valem mais",
      "dado": "Os 31% de clientes que compram duas vezes ou mais geram 57,5% da receita",
      "uso": "Sustenta a régua de reposição: cada segunda compra tem peso alto na receita."
    },
    {
      "titulo": "Prova social robusta",
      "dado": "Mais de 900 avaliações no sérum, com cerca de 60% citando textura e resultado",
      "uso": "Material pronto para campanhas de remarketing e conteúdo, sem depender de desconto."
    },
    {
      "titulo": "Margem bruta declarada",
      "dado": "68% declarados pelo cliente (62% nos kits), ainda sem confirmação",
      "uso": "Dá espaço para investir em CRM e estoque. Só vira argumento depois que a Luiza confirmar a margem por SKU."
    }
  ]
}
